-- Fault after inserting a Problem: an exception during challenge insertion must undo every earlier business row.
create function pg_temp.reject_challenge() returns trigger language plpgsql as $$begin raise exception 'challenge_fault_injected'; end$$;
create trigger mcp_v2_test_challenge_failure before insert on public.problem_initial_idea_mcp_challenges for each row execute function pg_temp.reject_challenge();
insert into test_ops values('fault',public.begin_mcp_operation_v2('d1400000-0000-4000-8000-000000000001','create_problem','create_problem','v2_create_fault_001',repeat('e',64),'{"initial_idea_draft":"草稿"}','pat','d1400000-0000-4000-8000-000000000011'));
