create function pg_temp.approve_edit(p_kind text,p_id uuid,p_changes jsonb,p_request text) returns text language plpgsql as $$
declare v_op jsonb;v_tool text;
begin
 v_tool:=case p_kind when 'note' then 'update_notebook_note' when 'word' then 'update_word_entry' else 'update_todo' end;
 v_op:=public.begin_mcp_operation_v2('d1400000-0000-4000-8000-000000000001',v_tool,v_tool,p_request,repeat('3',64),'{}','pat','d1400000-0000-4000-8000-000000000011');
 v_op:=public.propose_mcp_update_v2('d1400000-0000-4000-8000-000000000001',(v_op->>'id')::uuid,(v_op->>'lease_token')::uuid,p_kind,p_id,p_changes,1,null);
 perform public.preview_mcp_operation_v2((v_op->>'id')::uuid,repeat('d',64));
 return public.decide_mcp_operation_v2((v_op->>'id')::uuid,repeat('d',64),'approved')->>'state';
end;
$$;
