create function pg_temp.commit_insert(p_tool text,p_table text,p_row jsonb,p_request text) returns jsonb language plpgsql as $$
declare v_op jsonb;
begin
 v_op:=public.begin_mcp_operation_v2('d1400000-0000-4000-8000-000000000001',p_tool,p_tool,p_request,repeat('7',64),'{}','pat','d1400000-0000-4000-8000-000000000011');
 perform public.prepare_mcp_operation_v2('d1400000-0000-4000-8000-000000000001',(v_op->>'id')::uuid,(v_op->>'lease_token')::uuid,jsonb_build_object('kind','insert','table',p_table,'row',p_row));
 return public.commit_mcp_operation_v2('d1400000-0000-4000-8000-000000000001',(v_op->>'id')::uuid,(v_op->>'lease_token')::uuid);
end;
$$;
