select is(pg_temp.commit_insert('add_word_entry','word_entries','{"deck_id":"d1400000-0000-4000-8000-000000000032","word":"apple","normalized_word":"apple","meaning":"should not overwrite"}','v2_word_conflict1')->'error'->>'code','word_entry_exists','add_word_entry cannot overwrite an existing normalized word');
